import sys, os, json, urllib.request, urllib.error
sys.path.insert(0, "/data/scripts")

def _run():
    item = _items[0].get("json", {}) if _items else {}
    body = item.get("body", item) if isinstance(item.get("body"), dict) else item
    if not isinstance(body, dict):
        body = {}

    action = str(body.get("action") or "start").lower()
    api = os.environ.get("SITE_CLONE_API_URL") or "http://site-clone-api:7052"
    api = api.rstrip("/")

    def _as_dict(value, fallback):
        return value if isinstance(value, dict) else dict(fallback)

    def _http(method, path, payload=None, timeout=30):
        target = api + path
        try:
            data = None if payload is None else json.dumps(payload).encode()
            req = urllib.request.Request(target, data=data, method=method,
                                         headers={"Content-Type": "application/json", "Accept": "application/json"})
            with urllib.request.urlopen(req, timeout=timeout) as r:
                raw = r.read().decode() or "{}"
                try:
                    parsed = json.loads(raw)
                except Exception:
                    parsed = {}
                if not isinstance(parsed, dict):
                    parsed = {}
                if parsed:
                    return r.status, parsed
                return r.status, {"ok": False, "error": "invalid JSON from site-clone-api at %s" % target}
        except urllib.error.HTTPError as e:
            try:
                err = json.loads(e.read().decode() or "{}")
            except Exception:
                err = {}
            if not isinstance(err, dict):
                err = {}
            err.setdefault("ok", False)
            err.setdefault("error", "HTTP %s from site-clone-api at %s" % (e.code, target))
            return e.code, err
        except Exception as e:
            return 0, {"ok": False, "error": "site-clone-api unreachable at %s (%s)" % (target, type(e).__name__)}

    def _reply(obj, **extra):
        out = _as_dict(obj, {"ok": False, "error": "invalid response from site-clone-api at %s" % api})
        out.update(extra)
        return [{"json": out}]

    if action in ("start", "clone"):
        options = body.get("options")
        if not isinstance(options, dict):
            options = body
        payload = {
            "url": body.get("url") or "",
            "campaign_id": body.get("campaign_id") or "",
            "job_id": body.get("job_id") or "",
            "options": options,
            "opsec": body.get("opsec") or {},
            "proxy": body.get("proxy") or {},
        }
        code, data = _http("POST", "/clone", payload)
        if not data.get("ok") and not data.get("job_id"):
            return _reply({"ok": False, "error": data.get("error") or "clone start failed", "http": code, "api": api})
        data["ok"] = True
        data["http"] = code
        return _reply(data)

    job_id = str(body.get("job_id") or "")
    if action == "cancel":
        if not job_id:
            return _reply({"ok": False, "error": "job_id required"})
        code, data = _http("POST", "/jobs/%s/cancel" % job_id, {})
        data["ok"] = bool(data.get("ok"))
        data["http"] = code
        return _reply(data)

    if action == "status":
        if not job_id:
            return _reply({"ok": False, "error": "job_id required"})
        code, data = _http("GET", "/jobs/%s" % job_id)
        if code == 404:
            return _reply({"ok": False, "error": "unknown job", "http": code, "api": api})
        if code == 0 or (not data.get("status") and data.get("error")):
            return _reply({"ok": False, "error": data.get("error") or ("site-clone-api unreachable at %s" % api), "http": code, "api": api})
        # When the clone has finished, push findings into the campaign sketch once
        # and index the offline tree into the Prompt-tab company-site RAG corpus.
        # Indexing is fail-open and retried on later status polls if it has not yet
        # succeeded; it never contacts the target.
        if data.get("status") == "done":
            sketch = str(body.get("sketch_id") or "")
            analysis = (data.get("analysis") or {})
            ingested = data.get("ingested") if isinstance(data.get("ingested"), dict) else None
            campaign_id = str(body.get("campaign_id") or data.get("campaign_id") or "")
            wrote = False
            if sketch and analysis.get("ok") and not ingested:
                try:
                    import site_clone_ingest
                    ingested = site_clone_ingest.ingest_findings(
                        analysis, sketch,
                        campaign_id=campaign_id,
                        job_id=job_id,
                    )
                    wrote = True
                except Exception as e:
                    ingested = {"ok": False, "error": type(e).__name__ + ": " + str(e)[:200]}
                    wrote = True
            ingested = ingested or {}
            rag = ingested.get("site_rag") if isinstance(ingested.get("site_rag"), dict) else {}
            if sketch and not rag.get("ok"):
                try:
                    import site_rag
                    clones_root = os.environ.get("SITE_CLONE_DATA") or "/data/clones"
                    job_dir = os.path.join(clones_root, campaign_id or "unknown", job_id)
                    rag = site_rag.index_offline_tree(
                        job_dir,
                        sketch_id=sketch,
                        start_url=str(data.get("url") or analysis.get("start_url") or ""),
                        job_id=job_id,
                        campaign_id=campaign_id,
                    )
                except Exception as e:
                    rag = {"ok": False, "error": type(e).__name__ + ": " + str(e)[:200],
                           "chunks_indexed": 0}
                ingested["site_rag"] = rag
                wrote = True
            if ingested:
                data["ingested"] = ingested
            if wrote:
                try:
                    _http("POST", "/jobs/%s/ingested" % job_id, ingested)
                except Exception:
                    pass
        data["ok"] = True
        return _reply(data)

    if action == "source":
        if not job_id:
            return _reply({"ok": False, "error": "job_id required"})
        payload = {
            "campaign_id": str(body.get("campaign_id") or ""),
            "path": body.get("path") or body.get("source_path") or "",
            "line": body.get("line") or body.get("source_line") or 0,
            "evidence": body.get("evidence") or "",
            "context": body.get("context") or 20,
        }
        code, data = _http("POST", "/jobs/%s/source" % job_id, payload, timeout=20)
        if not isinstance(data, dict):
            data = {"ok": False, "error": "invalid source response"}
        data["http"] = code
        return _reply(data)

    return _reply({"ok": False, "error": "unknown action"})

try:
    return _run()
except Exception as e:
    return [{"json": {"ok": False, "error": "site-clone workflow failed: %s: %s" % (type(e).__name__, str(e)[:200])}}]
